C(6, 1, "No solo sobrevivir", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Estos años son para sobrevivir, o para aprovechar?"),
 ("papa", "mario", "[papá, cansado, resignado] Nomás aguantar tantito, y ya se le pasa."),
  ("joven", "rewe", "[adolescente, casual, bajito] Siento que nomás me soportan."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] En Edad de oportunidades, Paul David Tripp invita a los papás de adolescentes a mirar esta etapa de otra manera. No como una etapa para solo aguantar, sino como años de oportunidades. Y eso cambia todo."),
 ("cita", "marisol", "[firme, cálido, pausado] Lo dice así, en una frase que cambia el enfoque: «No son años solo para sobrevivir»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Tripp habla de tres puertas de oportunidad. Primera: su inseguridad. Segunda: su rebeldía. Tercera: su mundo, que cada vez es más grande. Por esas puertas puede entrar todo papá de un adolescente. Cada problema se puede volver una oportunidad de acercarte."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: la próxima vez que algo de tu hijo te irrite, pregúntate si es solo un fastidio, o una puerta para acercarte a él. Empieza por una."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: lo que revela nuestro enojo."),
], [
 ("titular", "gancho", "sobrevivir", "¿Sobrevivir o aprovechar?", "Salvavidas a la izquierda, brújula a la derecha; la brújula se ilumina"),
 ("reaccion", "papa", "aguantar", "Nomás aguantar tantito...", "Burbuja de papá con reloj de arena"),
 ("reaccion", "joven", "soportan", "Siento que nomás me soportan", "Burbuja apagada del adolescente"),
 ("titular", "idea", "oportunidades", "Años de oportunidades", "«oportunidades» en morado con subrayado amarillo"),
 ("cita", "cita", "sobrevivir", "«No son años solo para sobrevivir»", "Tarjeta de cita: Paul David Tripp, Edad de oportunidades"),
 ("icono", "giro", "Primera", "Puerta 1: su inseguridad", "Puerta con candado de cristal que se abre"),
 ("icono", "giro", "Segunda", "Puerta 2: su rebeldía", "Puerta con marcas de golpes que se abre"),
 ("icono", "giro", "Tercera", "Puerta 3: su mundo creciente", "Puerta que se abre a un horizonte amplio"),
 ("accion", "accion", "fastidio", "Para hoy: ¿fastidio o puerta?", "Tarjeta «Para hoy» con una puerta entreabierta"),
 ("titular", "siguiente", "enojo", "Siguiente: lo que revela nuestro enojo", "Palabra «enojo» con un espejo"),
], [SM + " (cap. 1: tres puertas de oportunidad; «¡No son años solo para sobrevivir!»)"])

C(6, 2, "Lo que revela tu enojo", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Te has enojado por una mala calificación? ¿Qué sentiste, de verdad?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Paul David Tripp cuenta de un papá tan enojado por la boleta de calificaciones de su hijo, que apenas podía ser educado. Fíjate qué le dijo."),
 ("papa", "mario", "[papá, furioso, tajante] «¿Cómo te atreves a hacerme esto después de todo lo que he hecho por ti?»"),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Tripp observa que ese papá no estaba enojado porque su hijo hubiera pecado contra Dios. Estaba enojado por lo que sentía perdido: su reputación, el respeto que creía merecer y su tranquilidad. Es decir, su enojo hablaba más de lo que él perdía que de lo que su hijo hacía."),
 ("joven", "rewe", "[adolescente, apagado, bajito] Hasta ahí llegó la plática."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: la próxima vez que te enojes con tu hijo, haz una pausa y pregúntate: ¿me duele lo que él hizo, o lo que yo siento que perdí? Sin culparte. Solo observa."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: por qué estos años nos ponen al descubierto."),
], [
 ("titular", "gancho", "calificación", "¿Enojo por una calificación?", "Boleta con números rojos sobre un escritorio; sin rostros"),
 ("ilustracion", "idea", "boleta", "La boleta, sobre la mesa", "Papel que avanza hacia el borde de la mesa"),
 ("cita", "papa", "atreves", "«¿Cómo te atreves a hacerme esto después de todo lo que he hecho por ti?»", "Tarjeta de cita: palabras de un papá, relatadas por Paul David Tripp en Edad de oportunidades"),
 ("icono", "giro", "reputación", "Su reputación", "Medalla que se resquebraja"),
 ("icono", "giro", "respeto", "Su respeto", "Corona que se inclina"),
 ("icono", "giro", "tranquilidad", "Su tranquilidad", "Taza de café que se derrama"),
 ("reaccion", "joven", "plática", "Hasta ahí llegó la plática", "Burbuja apagada del adolescente que se desvanece"),
 ("accion", "accion", "pausa", "Para hoy: pausa y pregunta", "Tarjeta «Para hoy» con símbolo de pausa"),
 ("titular", "accion", "perdí", "¿Me duele lo que él hizo, o lo que yo perdí?", "Dos platillos de balanza con las dos preguntas"),
 ("titular", "siguiente", "descubierto", "Siguiente: años que nos ponen al descubierto", "Cortina que se abre"),
], [SM + " (cap. 1: el papá y la boleta de calificaciones)"])

C(6, 3, "El telón se abre", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] A veces la adolescencia de tu hijo te muestra algo de ti."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Tripp escribe que las dificultades de la adolescencia no tienen que ver solo con la biología y la rebeldía. También sacan a la luz pensamientos y deseos equivocados en el corazón de los propios padres. Incómodo, pero útil."),
 ("cita", "marisol", "[firme, cálido, pausado] Lo resume así: «Estos años son difíciles porque retiran el telón y nos exponen»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Menciona nuestra impaciencia, nuestra justicia propia y nuestra falta de perdón. Y cuenta que, en su experiencia, cuando los padres lo reconocen con humildad, se nota una diferencia marcada en su relación con sus hijos."),
 ("papa", "mario", "[papá, humilde, tranquilo] Hijo, perdóname. Me desesperé y no te escuché."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: piensa en la última vez que perdiste la paciencia con tu hijo. Si hace falta, ofrécele una disculpa sencilla. Sin discurso y sin excusas."),
 ("tarjeta", "marisol", TARJ + "Edad de oportunidades, de Paul David Tripp, de P&R Publishing. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "ti", "Te muestra algo de ti", "Espejo con silueta, sin rostro"),
 ("icono", "idea", "biología", "No solo biología y rebeldía", "Dos íconos (célula, rayo) con una tercera pieza que se suma: un corazón"),
 ("cita", "cita", "telón", "«Estos años son difíciles porque retiran el telón y nos exponen»", "Tarjeta de cita: Paul David Tripp, Edad de oportunidades"),
 ("ilustracion", "cita", "telón", "El telón se abre", "Telón de teatro que se abre y deja ver un escenario vacío"),
 ("icono", "giro", "impaciencia", "Impaciencia", "Reloj con manecillas aceleradas"),
 ("icono", "giro", "perdón", "Falta de perdón", "Puño cerrado que se abre"),
 ("titular", "giro", "humildad", "Con humildad, la relación cambia", "«humildad» en morado con subrayado amarillo"),
 ("reaccion", "papa", "perdóname", "Hijo, perdóname. Me desesperé y no te escuché.", "Burbuja de papá, color cálido"),
 ("accion", "accion", "disculpa", "Para hoy: una disculpa sencilla, sin discurso", "Tarjeta «Para hoy» con palomita"),
 ("tarjeta_libro", "tarjeta", "Publishing", "Edad de oportunidades · Paul David Tripp · P&R Publishing", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [SM + " (cap. 1: «retiran el telón y nos exponen»)"])
